  for (let i = 0; i < (n || 1); i++) mark('st:' + ip, 60000);
  if (cnt('st:' + ip, 60000) >= 60 && !bans.has(ip)) { bans.set(ip, now() + 600000); console.warn('[보안] 과도한 요청으로 10분 차단:', ip); }
