  const room = mkRoom({ id: 'g_' + rnd(8), type: 'group', name: clean(r.name, 30), owner: u.id });
  addMember(room, u.id); ids.forEach(i => addMember(room, i));
  sysMsg(room, nameIn(room, u.id) + '님이 ' + namesOf(room, ids, u.id) + '님을 초대했습니다');
  pushRoomSync(room); return { roomId: room.id };
