const GREET = ['반갑습니다', '환영합니다', '환영해요', '안녕하세요', 'ㅇㄴㅎㅅㅇ', 'ㅎㅇ요', '하이요', '와주셔서감사합니다'];
const GREET_P = 0.001, STICKER_P = +process.env.GUEST_STICKER_P || 0.02;   // 사람이 들어올 때 게스트 한 명당: 인사 0.1% · (활동 시간대에) 스티커 2%
